from __future__ import absolute_import
from hran_radio.radio_output_parser.wmp_parser import TxPowerWMP, RxPowerWMP, RxStatWMP, TxStatWMP
from hran_radio.radio_connection.telnet_interface import TelnetConnection
from .radio_base import RadioBase


class RadioWMP(RadioBase):
    def __init__(self, radio_ip, system_module_ip, master_system_module_ip):
        super(RadioWMP, self).__init__(
            radio_ip, system_module_ip, master_system_module_ip
        )
        self.radio_connection = TelnetConnection(
            self._radio_ip, self._sm_ip, self._msm_ip, "2323"
        )
        self.release = self.radio_connection.get_smod_release()

    def all_tx_power(self):
        """
        Return all tx power in format {tx: power}.

        :return: tx power
        :rtype: dict
        """
        raw_output = self.run_radio_command("tx -power")
        tx_power = TxPowerWMP(raw_output)
        return tx_power.parse_tx_power()

    def all_rx_power(self):
        """
        Return all rx power in format {rx: power}.

        :return: rx power
        :rtype: dict
        """
        raw_output = self.run_radio_command("rx -power")
        rx_power = RxPowerWMP(raw_output)
        return rx_power.parse_rx_power()

    def lte_tx_power(self):
        """
        Return tx power for LTE technology.

        :return: tx power
        :rtype: dict
        """
        return self._get_tx_power_for("EUTRA")

    def wcdma_tx_power(self):
        """
        Return tx power for WCDMA technology.

        :return: tx power
        :rtype: dict
        """
        return self._get_tx_power_for("UTRA")

    def gsm_tx_power(self):
        """
        Return tx power for GSM technology.

        :return: tx power
        :rtype: dict
        """
        return self._get_tx_power_for("GSM")

    def front_end_gain(self, rx):
        """
        Return front end gain for rx.

        :return: front end gain
        :rtype: float
        """
        raw_output = self.run_radio_command("rx -stat")
        rx_stat = RxStatWMP(raw_output)
        return rx_stat.parse_front_end_gain()[str(rx)]

    def tx_carrier_data(self):
        """
        Return tx carrier data.

        :return: tx carrier data
        :rtype: dict
        """
        tx_stat = self._set_up_tx_stat()
        return tx_stat.parse_carrier_by_antenna()

    def rx_carrier_data(self):
        """
        Return rx carrier data.

        :return: rx carrier data
        :rtype: dict
        """
        raw_output = self.run_radio_command("rx -stat")
        rx_stat = RxStatWMP(raw_output)
        return rx_stat.parse_carrier_by_antenna()

    def _get_tx_power_for(self, technology):
        tx_power_dict = self.all_tx_power()
        tx_stat = self._set_up_tx_stat()
        tx_tech = tx_stat.get_tx_per_technology()
        return {
            tx_num: power
            for tx_num, power in tx_power_dict.items()
            if tx_tech[tx_num] == technology
        }

    def _set_up_tx_stat(self):
        raw_output = self.run_radio_command("tx -stat")
        return TxStatWMP(raw_output)
